190	/// Create a persistent watch session. Returns session ID.
191	/// Call this in Vite's configResolved hook.
192	#[napi]
193	pub fn create_session(options: JsExtractOptions) -> napi::Result<u32> {
194	    match oxc_react_docgen_core::panic_guard::contain_panic("create_session", move || {
195	        let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
196	
197	        #[cfg(test)]
198	        if pipeline_options.src_dirs.iter().any(|d| d.as_str() == CREATE_SESSION_PANIC_TEST_SENTINEL) {
199	            panic!("simulated create_session panic (test-only sentinel)");
200	        }
201	
202	        let id = next_session_id();
203	        let session = Arc::new(WatchSession::new(pipeline_options));
204	        SESSIONS.insert(id, session);
205	        Ok(id)
206	    }) {
207	        Ok(result) => result,
208	        Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
209	    }
210	}
