499	        assert!(first.is_ok(), "expected Ok for an unrecognized session_id, got {first:?}");
500	        assert!(SESSIONS.get(&session_id).is_some(), "expected the session to now be registered");
501	
502	        let second = extract_file_incremental("Widget.tsx".to_string(), session_id, base_options()).await;
503	        assert!(second.is_ok(), "expected Ok on reuse, got {second:?}");
504	    }
505	
506	    // ── SPEC-BINDING-001 AC11: close_session on an unrecognized or
507	    // already-removed session_id returns normally, no error.
