141	/// Reverse dependency graph: file → list of files that import from it.
142	/// Built once from GlobalSourceData; used by WatchSession for BFS propagation.
143	pub struct ReverseDeps {
144	    pub(super) inner: FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>>,
145	}
