121	pub(super) fn resolve_named_to_string_literals(
122	    name: &str,
123	    consuming_file: &Utf8Path,
124	    ctx: &ResolutionContext,
125	    state: &mut ResolveState,
126	    depth: u8,
127	) -> Option<Vec<String>> {
128	    let (canonical_file, canonical_name) = resolve_to_canonical(name, consuming_file, ctx, &mut state.diagnostics)
129	        .unwrap_or_else(|| (consuming_file.to_owned(), name.to_owned()));
130	
131	    let scoped_key = format!("{}:{}", canonical_file, canonical_name);
132	
133	    if let Some(alias) = ctx.global.type_aliases.get(&scoped_key) {
134	        match alias {
135	            CollectedTypeAlias::LiteralUnion { members, .. } => {
136	                return Some(members.clone());
137	            }
138	            CollectedTypeAlias::Union { members, .. } => {
139	                let strs: Option<Vec<String>> = members
140	                    .iter()
141	                    .map(|m| if let CollectedType::StringLiteral(s) = m { Some(s.to_string()) } else { None })
142	                    .collect();
143	                return strs;
144	            }
145	            _ => {}
146	        }
147	    }
148	
149	    // Try resolving via resolve_collected_type and extracting literals.
150	    let ct = CollectedType::Named { name: name.into(), args: vec![] };
151	    let pt = resolve_collected_type(&ct, consuming_file, ctx, state, depth);
152	    match pt {
153	        PropType::StringLiteral(s) => Some(vec![s]),
154	        PropType::LiteralUnion { members, .. } => Some(members),
155	        PropType::Union(members) => {
156	            members.into_iter().map(|m| if let PropType::StringLiteral(s) = m { Some(s) } else { None }).collect()
157	        }
158	        _ => None,
159	    }
