5	/// Walk `src_dirs` and collect every `.ts` / `.tsx` file, excluding:
6	/// - Built-in patterns: `.stories.`, `.test.`, `.spec.`, `__snapshots__`, `node_modules`
7	/// - User-supplied extra exclude patterns
8	///
9	/// Returns discovered files alongside any diagnostics raised while walking
10	/// (e.g. a permission-denied subtree) — never dropped silently (CLAUDE.md
11	/// non-negotiable #6).
12	pub(super) fn discover_files(
13	    src_dirs: &[Utf8PathBuf],
14	    extra_excludes: &[String],
15	) -> (Vec<Utf8PathBuf>, Vec<Diagnostic>) {
16	    let mut files = Vec::new();
17	    let mut diagnostics = Vec::new();
18	
