1	//! Named type resolution.
2	
3	use camino::Utf8Path;
4	use compact_str::CompactString;
5	
6	use crate::known::{push_known_opaque_diagnostic, KnownPatternResult};
7	use crate::react_types;
8	use crate::types::*;
9	
10	use super::alias::resolve_type_alias_type;
11	use super::collected::resolve_collected_type;
12	use super::import::{lookup_ambient_global, AmbientGlobalLookup};
13	use super::react::react_type_to_prop_type;
14	use super::{ResolutionContext, MAX_DEPTH};
15	
16	#[allow(clippy::too_many_arguments)]
17	pub(super) fn resolve_named(
18	    name: &CompactString,
19	    args: &[CollectedType],
20	    consuming_file: &Utf8Path,
21	    ctx: &ResolutionContext,
22	    state: &mut ResolveState,
23	    depth: u8,
24	) -> PropType {
25	    if depth > MAX_DEPTH {
26	        let diag = super::max_depth_diagnostic(&format!("named type '{}'", name), consuming_file);
27	        return OpaqueDetail::give_up(state, name.to_string(), OpaqueReason::DepthExceeded, diag);
28	    }
29	
30	    // ── 1. React builtin check ────────────────────────────────────────────────
31	    let lookup_name = name.strip_prefix("React.").unwrap_or(name.as_str());
32	    if react_types::is_react_builtin(lookup_name, &ctx.extra_builtins) {
33	        return react_type_to_prop_type(name.as_str(), args, consuming_file, ctx, state, depth);
34	    }
35	
36	    // Resolve type arguments eagerly — needed for both source lookups and known patterns.
37	    let resolved_args: Vec<PropType> =
38	        args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
39	
40	    // ── 2-5. Try the project's own source before a known-pattern shortcut ────
41	    // See `resolver::precedence` — the shared, single-source-of-truth order.
42	    let (canonical_file, canonical_name, matched) =
43	        super::precedence::resolve_source_defined_or_known(name.as_str(), &resolved_args, consuming_file, ctx, state);
44	
45	    match matched {
46	        Some(super::precedence::SourceOrKnownMatch::TypeAlias { matched_key, alias }) => {
47	            // A generic alias's own declared type parameters (`type Foo<TData> = ...`)
48	            // are expected, unexpandable placeholders wherever referenced in its body —
49	            // not unresolvable types. Register them so step 7 below doesn't warn.
50	            if let Some(params) = ctx.global.type_alias_params.get(&matched_key) {
51	                state.in_scope_type_params.extend(params.iter().cloned());
52	            }
53	            return resolve_type_alias_type(&alias, ctx, state, depth);
