1	//! DTS cache — persists parsed `SourceData` across runs to avoid re-parsing unchanged .d.ts files.
2	//!
3	//! Cache validity is based on file size + mtime (nanosecond resolution).
4	//! Schema version bumps automatically invalidate the entire cache.
5	//!
6	//! The cache never panics — load failures degrade gracefully to an empty
7	//! state, and save failures are reported via a `Diagnostic` (see
8	//! `save_to_disk`) rather than swallowed.
9	
10	use camino::{Utf8Path, Utf8PathBuf};
11	use dashmap::DashMap;
12	use serde::{Deserialize, Serialize};
13	use std::time::SystemTime;
14	
15	use crate::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity, SourceData};
16	
17	/// Bump this whenever `SourceData`'s field list or field order changes.
18	/// Serialization is via plain `rmp_serde::to_vec`/`from_slice` — MessagePack's
19	/// *positional* (not named-map) struct encoding — so inserting a field
20	/// anywhere but the very end shifts every subsequent field's decode position
21	/// for any cache entry written before the change. A same-shaped field
22	/// addition (e.g. another `FxHashMap<String, Vec<X>>`) wouldn't even fail
23	/// loudly; it would decode as plausible-looking but wrong data. `const_arrays`
24	/// (added mid-struct, not appended) is exactly this case — this bump covers it.
25	const CACHE_SCHEMA_VERSION: u32 = 2;
26	
27	// ─── Internal key type ────────────────────────────────────────────────────────
28	
29	#[derive(Hash, Eq, PartialEq, Clone)]
30	struct CacheKey {
31	    path: Utf8PathBuf,
32	    size: u64,
33	    mtime_ns: u128,
34	}
35	
36	// ─── Serializable surrogate (rmp-serde doesn't support u128) ─────────────────
37	
38	#[derive(Serialize, Deserialize)]
39	struct SerializableCacheKey {
40	    path: String,
41	    size: u64,
42	    /// Truncated to u64 nanoseconds — sufficient for several decades.
43	    mtime_ns: u64,
44	}
45	
46	impl From<&CacheKey> for SerializableCacheKey {
47	    fn from(k: &CacheKey) -> Self {
48	        Self { path: k.path.to_string(), size: k.size, mtime_ns: k.mtime_ns as u64 }
49	    }
50	}
51	
52	impl From<SerializableCacheKey> for CacheKey {
53	    fn from(k: SerializableCacheKey) -> Self {
54	        Self { path: Utf8PathBuf::from(k.path), size: k.size, mtime_ns: k.mtime_ns as u128 }
55	    }
56	}
57	
58	// ─── DtsCache ────────────────────────────────────────────────────────────────
59	
60	/// Maximum number of cached `.d.ts` entries allowed in memory/on disk.
61	const MAX_CACHE_ENTRIES: usize = 5000;
62	
63	/// Thread-safe DTS parse-result cache.
64	///
65	/// Keyed by `(path, size, mtime_ns)` — if the file hasn't changed, the cached
66	/// `SourceData` is returned directly without re-parsing.
67	pub struct DtsCache {
68	    store: DashMap<CacheKey, SourceData>,
69	    cache_dir: Utf8PathBuf,
70	    dirty: std::sync::atomic::AtomicBool,
71	}
72	
73	impl DtsCache {
74	    /// Load cache from disk.
75	    ///
76	    /// On any error (missing dir, schema mismatch, corrupt data) the cache
77	    /// starts empty — subsequent `insert` calls will repopulate it.
78	    ///
79	    /// `cache_dir` defaults to `node_modules/.cache/oxc-react-docgen/` relative
80	    /// to the current working directory.
81	    pub fn load_from_disk(cache_dir: Option<&Utf8Path>) -> Self {
82	        let dir = cache_dir
83	            .map(|p| p.to_owned())
84	            .unwrap_or_else(|| Utf8PathBuf::from("node_modules/.cache/oxc-react-docgen"));
85	
86	        let store = Self::try_load(&dir).unwrap_or_default();
87	        Self { store, cache_dir: dir, dirty: std::sync::atomic::AtomicBool::new(false) }
88	    }
89	
90	    fn try_load(dir: &Utf8Path) -> Option<DashMap<CacheKey, SourceData>> {
91	        // Check schema version via manifest first.
92	        let manifest_path = dir.join("manifest.json");
93	        let manifest_bytes = std::fs::read_to_string(manifest_path.as_std_path()).ok()?;
94	        let manifest: serde_json::Value = serde_json::from_str(&manifest_bytes).ok()?;
95	
96	        let schema = manifest["schema"].as_u64()?;
97	        if schema != CACHE_SCHEMA_VERSION as u64 {
98	            // Schema changed — discard entire cache.
99	            return None;
100	        }
101	
102	        let data_path = dir.join("dts-v1.msgpack");
103	        let bytes = std::fs::read(data_path.as_std_path()).ok()?;
104	
105	        let entries: Vec<(SerializableCacheKey, SourceData)> = rmp_serde::from_slice(&bytes).ok()?;
106	
107	        let map = DashMap::with_capacity(entries.len());
108	        for (k, v) in entries {
109	            map.insert(CacheKey::from(k), v);
110	        }
111	        Some(map)
112	    }
113	
114	    /// Look up cached `SourceData` for `path`.
115	    ///
116	    /// Returns `None` if the file is not cached or its mtime/size has changed.
117	    pub fn get(&self, path: &Utf8Path) -> Option<SourceData> {
118	        let key = self.key_for(path)?;
119	        self.store.get(&key).map(|v| v.clone())
120	    }
121	
122	    /// Insert `data` into the cache, keyed by `path`'s current mtime + size.
123	    ///
124	    /// Silently does nothing if the file metadata cannot be read.
125	    pub fn insert(&self, path: &Utf8Path, data: SourceData) {
126	        let Some(key) = self.key_for(path) else { return };
127	        // Evict extra entries if cache size exceeds MAX_CACHE_ENTRIES
128	        if self.store.len() >= MAX_CACHE_ENTRIES {
129	            let keys_to_evict: Vec<CacheKey> = self.store.iter().take(100).map(|r| r.key().clone()).collect();
130	            for k in keys_to_evict {
131	                self.store.remove(&k);
132	            }
133	        }
134	        self.store.insert(key, data);
135	        self.dirty.store(true, std::sync::atomic::Ordering::Relaxed);
136	    }
137	
138	    /// Persist the cache to disk atomically (temp file + rename).
139	    ///
140	    /// Skips writing if the cache is clean (no inserts since load). Never
141	    /// panics — on failure, returns a `Diagnostic` describing what went
142	    /// wrong (cache persistence is best-effort and must not fail the
143	    /// extraction run) instead of failing silently. Severity is `Info`, not
144	    /// `Warning`: a `Warning` here would flip `docgen check --strict`'s exit
145	    /// code to 1 purely because caching failed, even though extraction
146	    /// output itself is entirely correct — the exact class of spurious
147	    /// exit-code flip this project has already fixed once (see the
148	    /// resolver's discarded-return-type-resolution fix).
149	    pub fn save_to_disk(&self) -> Option<Diagnostic> {
150	        if !self.dirty.load(std::sync::atomic::Ordering::Relaxed) {
151	            return None;
152	        }
153	        self.try_save().err().map(|reason| Diagnostic {
154	            severity: DiagnosticSeverity::Info,
155	            message: format!("Failed to persist the DTS cache to '{}': {reason}", self.cache_dir),
156	            file: None,
157	            line: None,
158	            column: None,
159	            help: Some("Check that the cache directory is writable. Extraction still succeeded; only caching for the next run was affected.".into()),
160	            code: DiagnosticCode::IoError,
161	        })
162	    }
163	
164	    fn try_save(&self) -> Result<(), String> {
165	        std::fs::create_dir_all(self.cache_dir.as_std_path()).map_err(|e| e.to_string())?;
166	
167	        // Collect into a serializable form.
168	        let entries: Vec<(SerializableCacheKey, SourceData)> =
169	            self.store.iter().map(|r| (SerializableCacheKey::from(r.key()), r.value().clone())).collect();
170	
171	        let bytes = rmp_serde::to_vec(&entries).map_err(|e| e.to_string())?;
172	
173	        // Atomic write: write to tmp then rename (avoids half-written files on crash).
174	        let tmp_path = self.cache_dir.join("dts-v1.msgpack.tmp");
175	        let final_path = self.cache_dir.join("dts-v1.msgpack");
