208	            .modified()
209	            .ok()
210	            .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
211	            .map(|d| d.as_nanos())
212	            .unwrap_or(0);
213	
214	        Some(CacheKey { path: path.to_owned(), size: meta.len(), mtime_ns })
215	    }
