1	//! DTS cache — persists parsed `SourceData` across runs to avoid re-parsing unchanged .d.ts files.
2	//!
3	//! Cache validity is based on a content hash of the file's actual bytes, not
4	//! mtime/size (see `CacheKey`'s doc comment for why that was replaced).
5	//! Schema version bumps automatically invalidate the entire cache.
6	//!
7	//! The cache never panics — load failures degrade gracefully to an empty
8	//! state, and save failures are reported via a `Diagnostic` (see
9	//! `save_to_disk`) rather than swallowed.
10	
11	use camino::{Utf8Path, Utf8PathBuf};
12	use dashmap::DashMap;
13	use serde::{Deserialize, Serialize};
14	use std::hash::Hasher;
15	
16	use crate::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity, SourceData};
17	
18	/// Bump this whenever `SourceData`'s field list or field order changes.
19	/// Serialization is via plain `rmp_serde::to_vec`/`from_slice` — MessagePack's
20	/// *positional* (not named-map) struct encoding — so inserting a field
21	/// anywhere but the very end shifts every subsequent field's decode position
22	/// for any cache entry written before the change. A same-shaped field
23	/// addition (e.g. another `FxHashMap<String, Vec<X>>`) wouldn't even fail
24	/// loudly; it would decode as plausible-looking but wrong data. `const_arrays`
25	/// (added mid-struct, not appended) is exactly this case — this bump covers it.
26	/// Also bumped for the mtime+size -> content-hash key change (P0-2 fix):
27	/// `SerializableCacheKey`'s own shape changed, so pre-existing on-disk cache
28	/// files must be discarded rather than misread under the new field layout.
29	const CACHE_SCHEMA_VERSION: u32 = 3;
30	
31	// ─── Internal key type ────────────────────────────────────────────────────────
32	
33	/// Keyed by a hash of the file's actual byte content, not `(size, mtime)`.
34	///
35	/// The prior mtime+size scheme had a documented staleness gap (P0-2): on
36	/// filesystems/environments with coarse mtime resolution (network FS,
37	/// container overlay FS, or simply two edits landing in the same clock
38	/// tick), an edit completing within the same tick and producing a
39	/// same-length file was indistinguishable from the original — a stale
40	/// `SourceData` was served with no signal anything was wrong. A content hash
41	/// closes this gap exactly: two different byte sequences essentially never
42	/// hash to the same 64-bit `FxHasher` value (birthday-bound collision risk
43	/// is negligible at this cache's `MAX_CACHE_ENTRIES` scale), and identical
44	/// bytes always hash identically regardless of mtime/clock granularity.
45	/// This trades away the old stat-only check's near-zero I/O cost — computing
46	/// the hash requires the file's content, not just its metadata — but every
47	/// call site already reads the full file on a miss to parse it anyway; `get`
48	/// and `insert` both take that same content as a parameter instead of
49	/// re-deriving a (now-unreliable) proxy for it, so no call site pays for an
50	/// extra read this fix didn't already need.
51	#[derive(Hash, Eq, PartialEq, Clone)]
52	struct CacheKey {
53	    path: Utf8PathBuf,
54	    content_hash: u64,
55	}
56	
57	fn hash_content(content: &str) -> u64 {
58	    let mut hasher = rustc_hash::FxHasher::default();
59	    hasher.write(content.as_bytes());
60	    hasher.finish()
61	}
62	
63	// ─── Serializable surrogate ───────────────────────────────────────────────────
64	
65	#[derive(Serialize, Deserialize)]
66	struct SerializableCacheKey {
67	    path: String,
68	    content_hash: u64,
69	}
70	
71	impl From<&CacheKey> for SerializableCacheKey {
72	    fn from(k: &CacheKey) -> Self {
73	        Self { path: k.path.to_string(), content_hash: k.content_hash }
74	    }
75	}
76	
77	impl From<SerializableCacheKey> for CacheKey {
78	    fn from(k: SerializableCacheKey) -> Self {
79	        Self { path: Utf8PathBuf::from(k.path), content_hash: k.content_hash }
80	    }
81	}
82	
83	// ─── DtsCache ────────────────────────────────────────────────────────────────
84	
85	/// Maximum number of cached `.d.ts` entries allowed in memory/on disk.
86	const MAX_CACHE_ENTRIES: usize = 5000;
87	
88	/// Thread-safe DTS parse-result cache.
89	///
90	/// Keyed by `(path, size, mtime_ns)` — if the file hasn't changed, the cached
91	/// `SourceData` is returned directly without re-parsing.
92	pub struct DtsCache {
93	    store: DashMap<CacheKey, SourceData>,
94	    cache_dir: Utf8PathBuf,
95	    dirty: std::sync::atomic::AtomicBool,
96	}
97	
98	impl DtsCache {
99	    /// Load cache from disk.
100	    ///
101	    /// On any error (missing dir, schema mismatch, corrupt data) the cache
102	    /// starts empty — subsequent `insert` calls will repopulate it.
103	    ///
104	    /// `cache_dir` defaults to `node_modules/.cache/oxc-react-docgen/` relative
105	    /// to the current working directory.
106	    pub fn load_from_disk(cache_dir: Option<&Utf8Path>) -> Self {
107	        let dir = cache_dir
108	            .map(|p| p.to_owned())
109	            .unwrap_or_else(|| Utf8PathBuf::from("node_modules/.cache/oxc-react-docgen"));
110	
111	        let store = Self::try_load(&dir).unwrap_or_default();
112	        Self { store, cache_dir: dir, dirty: std::sync::atomic::AtomicBool::new(false) }
113	    }
114	
115	    fn try_load(dir: &Utf8Path) -> Option<DashMap<CacheKey, SourceData>> {
116	        // Check schema version via manifest first.
117	        let manifest_path = dir.join("manifest.json");
118	        let manifest_bytes = std::fs::read_to_string(manifest_path.as_std_path()).ok()?;
119	        let manifest: serde_json::Value = serde_json::from_str(&manifest_bytes).ok()?;
120	
121	        let schema = manifest["schema"].as_u64()?;
122	        if schema != CACHE_SCHEMA_VERSION as u64 {
123	            // Schema changed — discard entire cache.
124	            return None;
125	        }
126	
127	        let data_path = dir.join("dts-v1.msgpack");
128	        let bytes = std::fs::read(data_path.as_std_path()).ok()?;
129	
130	        let entries: Vec<(SerializableCacheKey, SourceData)> = rmp_serde::from_slice(&bytes).ok()?;
131	
132	        let map = DashMap::with_capacity(entries.len());
133	        for (k, v) in entries {
134	            map.insert(CacheKey::from(k), v);
135	        }
136	        Some(map)
137	    }
138	
139	    /// Look up cached `SourceData` for `path`, given its current content.
140	    ///
141	    /// Returns `None` if the file is not cached or its content hash has
142	    /// changed. `content` is a parameter rather than read internally because
143	    /// every call site already reads the file to parse it on a miss — taking
144	    /// content here means neither a hit nor a miss ever reads the file twice.
145	    pub fn get(&self, path: &Utf8Path, content: &str) -> Option<SourceData> {
146	        let key = self.key_for(path, content);
147	        self.store.get(&key).map(|v| v.clone())
148	    }
149	
150	    /// Insert `data` into the cache, keyed by `path` + a hash of `content`.
151	    pub fn insert(&self, path: &Utf8Path, content: &str, data: SourceData) {
152	        let key = self.key_for(path, content);
153	        // Evict extra entries if cache size exceeds MAX_CACHE_ENTRIES
154	        if self.store.len() >= MAX_CACHE_ENTRIES {
155	            let keys_to_evict: Vec<CacheKey> = self.store.iter().take(100).map(|r| r.key().clone()).collect();
156	            for k in keys_to_evict {
157	                self.store.remove(&k);
158	            }
159	        }
160	        self.store.insert(key, data);
161	        self.dirty.store(true, std::sync::atomic::Ordering::Relaxed);
162	    }
163	
164	    /// Persist the cache to disk atomically (temp file + rename).
165	    ///
166	    /// Skips writing if the cache is clean (no inserts since load). Never
167	    /// panics — on failure, returns a `Diagnostic` describing what went
168	    /// wrong (cache persistence is best-effort and must not fail the
169	    /// extraction run) instead of failing silently. Severity is `Info`, not
170	    /// `Warning`: a `Warning` here would flip `docgen check --strict`'s exit
171	    /// code to 1 purely because caching failed, even though extraction

