11	/// Peel any wrapping `as X` casts down to the real expression underneath.
12	/// Needed because component libraries commonly cast a forwardRef/HOC call to a
13	/// hand-rolled wrapper type instead of relying on `@types/react`'s own generics
14	/// (Fluent UI's own source notes this is "required due to lack of distributive
15	/// union to support unions on @types/react").
16	fn unwrap_as_expression<'a, 'b>(expr: &'b Expression<'a>) -> &'b Expression<'a> {
17	    let mut expr = expr;
18	    while let Expression::TSAsExpression(as_expr) = expr {
19	        expr = &as_expr.expression;
20	    }
21	    expr
22	}
23	
24	impl<'src> SourceDataCollector<'src> {
25	    // ─── Component detection helpers ──────────────────────────────────────────
26	
27	    /// Try to extract a PascalCase name from a VariableDeclarator's binding.
28	    pub(super) fn extract_pascal_name<'a>(&self, decl: &VariableDeclarator<'a>) -> Option<String> {
29	        match &decl.id {
30	            BindingPattern::BindingIdentifier(id) => {
31	                let name = id.name.as_str();
32	                if is_pascal_case(name) {
33	                    Some(name.to_owned())
34	                } else {
35	                    None
36	                }
37	            }
38	            _ => None,
39	        }
40	    }
41	
42	    /// Try to detect: `const Button: FC<ButtonProps> = ({ variant = 'primary' }) => ...`
43	    pub(super) fn try_fc_annotation<'a>(
44	        &mut self,
45	        decl: &VariableDeclarator<'a>,
46	        name: &str,
47	    ) -> Option<ComponentMapping> {
48	        let type_ann = decl.type_annotation.as_ref()?;
49	        let init_params = match decl.init.as_ref() {
50	            Some(Expression::ArrowFunctionExpression(afe)) => Some(&*afe.params),
51	            Some(Expression::FunctionExpression(fe)) => Some(&*fe.params),
52	            _ => None,
53	        };
54	        self.extract_props_from_type_annotation(
55	            &type_ann.type_annotation,
56	            name,
57	            decl.span.start,
58	            decl.span.end,
59	            init_params,
60	        )
61	    }
62	
63	    pub(super) fn extract_props_from_type_annotation<'a>(
64	        &mut self,
65	        ty: &TSType<'a>,
66	        name: &str,
67	        span_start: u32,
68	        span_end: u32,
69	        init_params: Option<&FormalParameters<'a>>,
70	    ) -> Option<ComponentMapping> {
71	        match ty {
72	            TSType::TSTypeReference(tr) => {
73	                let type_name = self.extract_type_ref_name(tr);
74	                let bare_name = type_name.strip_prefix("React.").unwrap_or(&type_name);
75	                if !matches!(
76	                    bare_name,
77	                    "FC" | "FunctionComponent"
78	                        | "ComponentType"
79	                        | "VFC"
80	                        | "VoidFunctionComponent"
81	                        | "ForwardRefComponent"
82	                ) {
83	                    return None;
84	                }
85	                let (props_name, type_args) = self.extract_props_arg(&tr.type_arguments)?;
86	                let (description, tags) = self.find_jsdoc_with_tags(span_start);
87	                Some(ComponentMapping {
88	                    component_name: name.to_owned(),
89	                    props_type_name: props_name,
90	                    props_type_args: type_args,
91	                    file_path: self.file_path.clone(),
92	                    description,
93	                    tags,
94	                    span_start,
95	                    span_end,
96	                    param_defaults: init_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default(),
97	                })
98	            }
99	            TSType::TSParenthesizedType(p) => {
100	                self.extract_props_from_type_annotation(&p.type_annotation, name, span_start, span_end, init_params)
101	            }
102	            _ => None,
103	        }
104	    }
105	
106	    /// Try to detect: `const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(...)`
107	    pub(super) fn try_forward_ref<'a>(
108	        &mut self,
109	        decl: &VariableDeclarator<'a>,
110	        name: &str,
111	    ) -> Option<ComponentMapping> {
112	        let init = decl.init.as_ref()?;
113	        let call = match unwrap_as_expression(init) {
114	            Expression::CallExpression(ce) => ce,
115	            _ => return None,
116	        };
117	        let callee_name = self.extract_callee_name(call)?;
118	
119	        if !matches!(callee_name.as_str(), "forwardRef" | "React.forwardRef") {
120	            return None;
121	        }
122	
123	        // forwardRef<RefType, PropsType>(fn) — PropsType is the second type parameter
124	        let type_params = call.type_arguments.as_ref()?;
125	        if type_params.params.len() < 2 {
126	            return None;
127	        }
128	        let props_type = &type_params.params[1];
129	        let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
130	
131	        // The render function is forwardRef's call argument — its first parameter is
132	        // props (the second is `ref`, which never carries destructured defaults we care about).
133	        let render_params = match call.arguments.first() {
134	            Some(Argument::FunctionExpression(fe)) => Some(&fe.params),
135	            Some(Argument::ArrowFunctionExpression(afe)) => Some(&afe.params),
136	            _ => None,
137	        };
138	        let param_defaults = render_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default();
139	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
140	
141	        Some(ComponentMapping {
142	            component_name: name.to_owned(),
143	            props_type_name: props_name,
144	            props_type_args: type_args,
145	            file_path: self.file_path.clone(),
146	            description,
147	            tags,
148	            span_start: decl.span.start,
149	            span_end: decl.span.end,
150	            param_defaults,
151	        })
152	    }
153	
154	    /// Try to detect: `const Button = anyHOC(function Button(props: ButtonProps) {...})`
155	    pub(super) fn try_hoc_wrapped<'a>(
156	        &mut self,
157	        decl: &VariableDeclarator<'a>,
158	        name: &str,
159	    ) -> Option<ComponentMapping> {
160	        let init = decl.init.as_ref()?;
161	        let call = match unwrap_as_expression(init) {
162	            Expression::CallExpression(ce) => ce,
163	            _ => return None,
164	        };
165	
166	        // First arg should be a function with a typed props param — or a forwardRef() call.
167	        let first_arg = call.arguments.first()?;
168	
169	        // Handle memo(forwardRef<Ref, Props>(...)) — inner call is forwardRef
170	        if let Argument::CallExpression(inner) = first_arg {
171	            if let Some(inner_name) = self.extract_callee_name(inner) {
172	                if matches!(inner_name.as_str(), "forwardRef" | "React.forwardRef") {
173	                    let type_params = inner.type_arguments.as_ref()?;
174	                    if type_params.params.len() >= 2 {
175	                        let (props_name, type_args) = self.extract_type_name_from_type(&type_params.params[1])?;
176	                        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
177	                        return Some(ComponentMapping {
178	                            component_name: name.to_owned(),
