1	//! OXC AST extractor — Phase 2a.
2	//!
3	//! Walks the OXC AST for a single file and collects everything into a [`SourceData`].
4	//!
5	//! **The Absolute Rule:** No AST references escape `parse_file`.
6	//! The `Allocator` is created locally, and all arena memory is freed when `parse_file` returns.
7	//! [`SourceData`] contains only owned data (String, Vec, etc.).
8	
9	use camino::{Utf8Path, Utf8PathBuf};
10	use compact_str::CompactString;
11	use oxc_allocator::{Allocator, Box as OxcBox};
12	use oxc_ast::ast::*;
13	use oxc_ast_visit::Visit;
14	use oxc_parser::Parser;
15	use oxc_span::{SourceType, Span};
16	use rustc_hash::FxHashSet;
17	
18	#[cfg(test)]
19	use crate::types::LexedExport;
20	use crate::types::{
21	    CollectedObjectField, CollectedType, CollectedTypeAlias, Diagnostic, DiagnosticCode, DiagnosticSeverity,
22	    ExtendsRef, RawProp, SourceData,
23	};
24	
25	mod alias;
26	mod component;
27	mod defaults;
28	mod interface;
29	mod jsdoc;
30	mod visit;
31	
32	// ─── Entry Point ─────────────────────────────────────────────────────────────
33	
34	/// Maximum bracket-nesting depth a source file may contain before we refuse to parse it.
35	///
36	/// `oxc_parser`'s recursive-descent grammar has no depth guard for nested parenthesized
37	/// types, object type literals, or conditional types — a file with ~6,000+ levels of
38	/// nesting deterministically stack-overflows the parser itself (confirmed via a
39	/// standalone parser-only harness). 2000 leaves a wide safety margin.
40	const MAX_SOURCE_NESTING_DEPTH: usize = 2000;
41	
42	/// Maximum AST recursion depth for `ts_type_to_collected` and its mutually
43	/// recursive siblings. `max_bracket_nesting_depth` bounds raw-text bracket
44	/// depth as a cheap pre-parse proxy for parser stack safety, but chained
45	/// conditional types (`A extends B ? C extends D ? ... : ... : ...`) add one
46	/// AST level per `? :` with no brackets at all — the proxy metric undercounts
47	/// exactly this shape. This counter guards the extractor's own recursion the
48	/// same way the resolver's `depth: u8` / `MAX_DEPTH` already guards
49	/// `resolve_collected_type` (see `resolver/mod.rs`), just at a higher ceiling
50	/// since this walk is a single in-process AST-to-struct conversion, not
51	/// cross-file resolution. `MAX_SOURCE_NESTING_DEPTH` (bracket-based) and this
52	/// constant (AST-based) are independent knobs and do not need to match.
53	const MAX_TYPE_COLLECT_DEPTH: u8 = 200;
54	
55	/// Cheap linear scan bounding the maximum bracket-nesting depth of `source`.
56	///
57	/// Only tracks a running max, not full balance — sufficient to bound recursion depth
58	/// before handing the source to the real parser. Comments and string/template
59	/// literals are skipped entirely rather than scanned for brackets: real .d.ts
60	/// files (TypeScript's own `lib.dom.d.ts` included) ship prose JSDoc with
61	/// unmatched brackets — e.g. MDN-scraped artifacts like `MISSING: RFC(5646,
62	/// '...')].` — that would otherwise drive `depth` negative and, once negative
63	/// enough, wrap on the next legitimate bracket. Doesn't track `${...}`
64	/// interpolation inside template literals as real nesting; under-counting a
65	/// rare template-literal type's internal depth is an acceptable trade-off for
66	/// a crash-prevention heuristic, never causing a false rejection.
67	fn max_bracket_nesting_depth(source: &str) -> usize {
68	    let bytes = source.as_bytes();
69	    let mut depth: usize = 0;
70	    let mut max_depth: usize = 0;
71	    let mut i = 0;
72	    while i < bytes.len() {
73	        match bytes[i] {
74	            b'/' if bytes.get(i + 1) == Some(&b'/') => {
75	                i += 2;
76	                while i < bytes.len() && bytes[i] != b'\n' {
77	                    i += 1;
78	                }
79	            }
80	            b'/' if bytes.get(i + 1) == Some(&b'*') => {
81	                i += 2;
82	                while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') {
83	                    i += 1;
84	                }
85	                i = (i + 2).min(bytes.len());
86	            }
87	            quote @ (b'\'' | b'"' | b'`') => {
88	                i += 1;
89	                while i < bytes.len() && bytes[i] != quote {
90	                    i += if bytes[i] == b'\\' && i + 1 < bytes.len() { 2 } else { 1 };
91	                }
92	                i = (i + 1).min(bytes.len());
93	            }
94	            b'(' | b'{' | b'[' => {
95	                depth += 1;
96	                max_depth = max_depth.max(depth);
97	                i += 1;
98	            }
99	            b')' | b'}' | b']' => {
100	                depth = depth.saturating_sub(1);
101	                i += 1;
102	            }
103	            _ => i += 1,
104	        }
105	    }
106	    max_depth
107	}
108	
109	/// Parse a single file and collect all extractable data.
110	///
111	/// Completely pure — no I/O, no side effects, no cross-file dependencies.
112	/// Safe to call in parallel from rayon workers.
113	///
114	/// Never panics on malformed input: excessive nesting and TypeScript syntax errors
115	/// are reported via `SourceData::diagnostics` rather than failing silently or
116	/// letting the parser overrun the stack.
117	pub fn parse_file(path: &Utf8Path, source: &str) -> SourceData {
118	    let observed_depth = max_bracket_nesting_depth(source);
119	    if observed_depth > MAX_SOURCE_NESTING_DEPTH {
120	        let mut data = SourceData::default();
121	        data.diagnostics.push(Diagnostic {
122	            severity: DiagnosticSeverity::Error,
123	            message: format!(
124	                "File exceeds maximum type nesting depth ({observed_depth} > {MAX_SOURCE_NESTING_DEPTH}), skipped to avoid parser stack overflow"
125	            ),
126	            file: Some(path.to_string()),
127	            line: None,
128	            column: None,
129	            help: Some("Reduce nested parenthesized/object/conditional types in this file.".into()),
130	            code: DiagnosticCode::ExcessiveNesting,
131	        });
132	        return data;
133	    }
134	
135	    let allocator = Allocator::default();
136	    let source_type = SourceType::from_path(path).unwrap_or_default();
137	    let ret = Parser::new(&allocator, source, source_type).parse();
138	
139	    // .d.ts declaration files use the same React.FC / ForwardRefExoticComponent patterns as .tsx
140	    let is_tsx = source_type.is_jsx() || source_type.is_typescript_definition();
141	    let mut collector = SourceDataCollector::new(path, source, is_tsx);
142	
143	    // oxc_parser is error-recovering: `ret.program` is still usable even when
144	    // `ret.errors` is non-empty. Surface each error as a diagnostic instead of
145	    // silently treating the source as if it parsed cleanly.
146	    for err in &ret.errors {
147	        collector.data.diagnostics.push(Diagnostic {
148	            severity: DiagnosticSeverity::Error,
149	            message: err.to_string(),
150	            file: Some(path.to_string()),
151	            line: None,
152	            column: None,
153	            help: None,
154	            code: DiagnosticCode::ParseError,
155	        });
156	    }
157	
158	    // Pass comments by cloning them into owned strings before the allocator drops.
159	    // The comments Vec lives in the arena; we extract them here.
160	    let comments: Vec<OwnedComment> = ret
161	        .program
162	        .comments
163	        .iter()
164	        .map(|c| OwnedComment { span_start: c.span.start, span_end: c.span.end, is_block: c.is_block() })
165	        .collect();
166	    collector.comments = comments;
167	    collector.visit_program(&ret.program);
168	    collector.finish()
169	    // allocator drops here — ALL arena memory freed
170	}
171	
172	// ─── Owned Comment (so nothing escapes the allocator) ────────────────────────
173	
174	#[derive(Debug, Clone)]
175	pub(super) struct OwnedComment {
176	    pub(super) span_start: u32,
177	    pub(super) span_end: u32,
178	    pub(super) is_block: bool,
179	}
