272	    // ─── Import source specifier lookup ──────────────────────────────────────
273	
274	    pub(super) fn find_import_specifier(&self, local_name: &str) -> Option<String> {
275	        self.data.imports.iter().find(|imp| imp.local_name.as_str() == local_name).map(|imp| imp.specifier.clone())
276	    }
