278	    // ─── ExtendsRef classification ────────────────────────────────────────────
279	
280	    pub(super) fn classify_extends(&self, name: &str, type_args: Vec<String>) -> ExtendsRef {
281	        // Strip "React." prefix for lookup in builtin tables
282	        let lookup_name = name.strip_prefix("React.").unwrap_or(name);
283	
284	        // SVGAttributes/SVGProps/HTMLProps carry no element in their own name —
285	        // unlike html_element_for's other entries (ButtonHTMLAttributes, etc.),
286	        // where the element is baked into the interface name itself. Real call
287	        // sites always supply a concrete DOM element as the type argument
288	        // (`SVGAttributes<SVGSVGElement>`, `HTMLProps<HTMLDivElement>`) — derive
289	        // the element from that instead of falling through to html_element_for's
290	        // static result (None for SVGAttributes/SVGProps, a generic "div"
291	        // fallback for HTMLProps) whenever it's one this crate recognizes.
292	        if matches!(lookup_name, "SVGAttributes" | "SVGProps" | "HTMLProps") {
293	            if let Some(element) = type_args.first().and_then(|arg| crate::react_types::html_element_from_type_arg(arg))
294	            {
295	                return ExtendsRef::Builtin { name: name.into(), element: Some(element.to_owned()), type_args };
296	            }
297	        }
298	
299	        if let Some(element) = crate::react_types::html_element_for(lookup_name) {
300	            return ExtendsRef::Builtin { name: name.into(), element: Some(element.to_owned()), type_args };
301	        }
302	        if crate::react_types::is_react_builtin(lookup_name, &rustc_hash::FxHashSet::default()) {
303	            return ExtendsRef::Builtin { name: name.into(), element: None, type_args };
304	        }
305	        // Check if imported
306	        if self.imported_names.contains(name) {
307	            return ExtendsRef::Imported {
308	                local_name: name.into(),
309	                type_args,
310	                source_specifier: self.find_import_specifier(name),
311	            };
312	        }
313	        ExtendsRef::SameFile { name: name.into(), type_args }
314	    }
