316	    // ─── TSTypeName → String ──────────────────────────────────────────────────
317	
318	    pub(super) fn ts_type_name_str<'a>(&self, name: &TSTypeName<'a>) -> String {
319	        match name {
320	            TSTypeName::IdentifierReference(id) => id.name.as_str().to_owned(),
321	            TSTypeName::QualifiedName(q) => {
322	                format!("{}.{}", self.ts_type_name_str(&q.left), q.right.name.as_str())
323	            }
324	            TSTypeName::ThisExpression(_) => "this".to_owned(),
325	        }
326	    }
