328	    // ─── TSTypeParameterInstantiation → Vec<String> ──────────────────────────
329	
330	    pub(super) fn extract_type_args<'a>(
331	        &mut self,
332	        type_params: &Option<OxcBox<'a, TSTypeParameterInstantiation<'a>>>,
333	    ) -> Vec<String> {
334	        match type_params {
335	            Some(tp) => tp.params.iter().map(|p| self.ts_type_to_collected_at_depth(p, 0).to_raw_string()).collect(),
336	            None => vec![],
337	        }
338	    }
