340	    // ─── TSType → CollectedType ───────────────────────────────────────────────
341	
342	    pub(super) fn ts_type_to_collected<'a>(&mut self, ty: &TSType<'a>) -> CollectedType {
343	        self.ts_type_to_collected_at_depth(ty, 0)
344	    }
345	
346	    fn ts_type_to_collected_at_depth<'a>(&mut self, ty: &TSType<'a>, depth: u8) -> CollectedType {
347	        if depth > MAX_TYPE_COLLECT_DEPTH {
348	            use oxc_span::GetSpan;
349	            let span = ty.span();
350	            self.data.diagnostics.push(Diagnostic {
351	                severity: DiagnosticSeverity::Warning,
352	                message: format!(
353	                    "Type nesting exceeds maximum extractor recursion depth ({depth} > {MAX_TYPE_COLLECT_DEPTH})"
354	                ),
355	                file: Some(self.file_path.to_string()),
356	                line: None,
357	                column: None,
358	                help: Some("This may indicate a deeply chained conditional or mapped type.".into()),
359	                code: DiagnosticCode::MaxDepthExceeded,
360	            });
361	            let raw = self.source[span.start as usize..span.end as usize].to_owned();
362	            return CollectedType::Raw(raw);
363	        }
364	        match ty {
365	            TSType::TSStringKeyword(_) => CollectedType::String,
366	            TSType::TSNumberKeyword(_) => CollectedType::Number,
367	            TSType::TSBooleanKeyword(_) => CollectedType::Boolean,
368	            TSType::TSNullKeyword(_) => CollectedType::Null,
369	            TSType::TSUndefinedKeyword(_) => CollectedType::Undefined,
370	            TSType::TSAnyKeyword(_) => CollectedType::Any,
371	            TSType::TSNeverKeyword(_) => CollectedType::Never,
372	            TSType::TSUnknownKeyword(_) => CollectedType::Unknown,
373	            TSType::TSVoidKeyword(_) => CollectedType::Void,
374	            TSType::TSBigIntKeyword(_) => CollectedType::BigInt,
375	            TSType::TSSymbolKeyword(_) => CollectedType::Symbol,
376	            TSType::TSObjectKeyword(_) => CollectedType::Named { name: "object".into(), args: vec![] },
377	
378	            TSType::TSLiteralType(lit) => match &lit.literal {
379	                TSLiteral::StringLiteral(s) => CollectedType::StringLiteral(s.value.as_str().into()),
380	                TSLiteral::NumericLiteral(n) => CollectedType::NumberLiteral(n.value),
381	                TSLiteral::BooleanLiteral(b) => CollectedType::BoolLiteral(b.value),
382	                TSLiteral::UnaryExpression(u) => {
383	                    // Handle negative numbers: -1
384	                    let raw = self.source[u.span.start as usize..u.span.end as usize].to_owned();
385	                    CollectedType::Raw(raw)
386	                }
387	                _ => CollectedType::Raw(self.source[lit.span.start as usize..lit.span.end as usize].to_owned()),
388	            },
389	
390	            TSType::TSTypeReference(tr) => {
391	                let name: CompactString = self.ts_type_name_str(&tr.type_name).into();
392	                let args = tr
393	                    .type_arguments
394	                    .as_ref()
395	                    .map(|ta| ta.params.iter().map(|p| self.ts_type_to_collected_at_depth(p, depth + 1)).collect())
396	                    .unwrap_or_default();
397	                CollectedType::Named { name, args }
398	            }
399	
400	            TSType::TSTypeQuery(q) => {
401	                let name = self.ts_type_query_name(q);
402	                CollectedType::TypeOf(name.into())
403	            }
404	
405	            TSType::TSUnionType(u) => {
406	                let members: Vec<CollectedType> =
407	                    u.types.iter().map(|t| self.ts_type_to_collected_at_depth(t, depth + 1)).collect();
408	                CollectedType::Union(members)
409	            }
410	
411	            TSType::TSIntersectionType(i) => {
412	                let members: Vec<CollectedType> =
413	                    i.types.iter().map(|t| self.ts_type_to_collected_at_depth(t, depth + 1)).collect();
414	                CollectedType::Intersection(members)
415	            }
416	
417	            TSType::TSArrayType(a) => {
418	                CollectedType::Array(Box::new(self.ts_type_to_collected_at_depth(&a.element_type, depth + 1)))
419	            }
420	
421	            TSType::TSTupleType(t) => {
422	                let members: Vec<CollectedType> =
423	                    t.element_types.iter().map(|el| self.ts_tuple_element_to_collected(el, depth + 1)).collect();
424	                CollectedType::Tuple(members)
425	            }
426	
427	            TSType::TSTypeLiteral(lit) => {
428	                let fields: Vec<CollectedObjectField> = lit
429	                    .members
430	                    .iter()
431	                    .filter_map(|member| self.ts_signature_to_object_field(member, depth + 1))
432	                    .collect();
433	                CollectedType::Object(fields)
434	            }
435	
436	            TSType::TSFunctionType(f) => {
437	                // In OXC 0.135, FormalParameter has type_annotation as a separate field
438	                let params: Vec<CollectedType> = f
439	                    .params
440	                    .items
441	                    .iter()
442	                    .map(|p| {
443	                        p.type_annotation
444	                            .as_ref()
445	                            .map(|ta| self.ts_type_to_collected_at_depth(&ta.type_annotation, depth + 1))
446	                            .unwrap_or(CollectedType::Any)
447	                    })
448	                    .collect();
449	                let param_names: Vec<Option<CompactString>> =
450	                    f.params.items.iter().map(|p| binding_pattern_name(&p.pattern)).collect();
451	                // return_type on TSFunctionType is Box<TSTypeAnnotation> (not Option)
452	                let return_type = self.ts_type_to_collected_at_depth(&f.return_type.type_annotation, depth + 1);
453	                CollectedType::Function { params, param_names, return_type: Box::new(return_type) }
454	            }
455	
456	            TSType::TSIndexedAccessType(ia) => CollectedType::IndexedAccess {
457	                obj: Box::new(self.ts_type_to_collected_at_depth(&ia.object_type, depth + 1)),
458	                key: Box::new(self.ts_type_to_collected_at_depth(&ia.index_type, depth + 1)),
459	            },
460	
461	            TSType::TSTemplateLiteralType(tl) => {
462	                let mut parts: Vec<CollectedType> = Vec::new();
463	                for (i, quasi) in tl.quasis.iter().enumerate() {
464	                    let s = quasi.value.raw.as_str();
465	                    if !s.is_empty() {
466	                        parts.push(CollectedType::StringLiteral(s.into()));
467	                    }
468	                    if let Some(ty) = tl.types.get(i) {
469	                        parts.push(self.ts_type_to_collected_at_depth(ty, depth + 1));
470	                    }
471	                }
472	                CollectedType::TemplateLiteral(parts)
473	            }
474	
475	            TSType::TSConditionalType(c) => CollectedType::Conditional {
476	                check: Box::new(self.ts_type_to_collected_at_depth(&c.check_type, depth + 1)),
477	                extends_type: Box::new(self.ts_type_to_collected_at_depth(&c.extends_type, depth + 1)),
478	                true_type: Box::new(self.ts_type_to_collected_at_depth(&c.true_type, depth + 1)),
479	                false_type: Box::new(self.ts_type_to_collected_at_depth(&c.false_type, depth + 1)),
480	            },
481	
482	            TSType::TSMappedType(m) => {
483	                // In OXC 0.135, TSMappedType has `constraint: TSType` directly (not via
484	                // type_parameter) and `type_annotation: Option<TSType>` (not Box<TSTypeAnnotation>)
485	                let key_type = self.ts_type_to_collected_at_depth(&m.constraint, depth + 1);
486	                let value_type = m
487	                    .type_annotation
488	                    .as_ref()
489	                    .map(|ta| self.ts_type_to_collected_at_depth(ta, depth + 1))
490	                    .unwrap_or(CollectedType::Unknown);
491	                CollectedType::Mapped { key_type: Box::new(key_type), value_type: Box::new(value_type) }
492	            }
493	
494	            TSType::TSParenthesizedType(p) => {
495	                // Unwrap parentheses — (Type) → Type
496	                self.ts_type_to_collected_at_depth(&p.type_annotation, depth + 1)
497	            }
498	
499	            // TSTypeOperatorType covers keyof, unique, readonly. `keyof` is kept
500	            // structured (its operand may itself need substitution or resolution —
501	            // see `CollectedType::KeyOf`). `readonly`/`unique` are peeled
502	            // transparently to their operand — docgen doesn't track mutability or
503	            // symbol uniqueness, so there's nothing to preserve — rather than
504	            // capturing the whole modified type as raw source text, which used to
505	            // make `readonly string[]` (real @types/react's ButtonHTMLAttributes
506	            // `defaultValue`/`value` shape) degrade to Opaque even though the
507	            // element type is fully knowable.
508	            TSType::TSTypeOperatorType(op) => match op.operator {
509	                TSTypeOperatorOperator::Keyof => {
510	                    CollectedType::KeyOf(Box::new(self.ts_type_to_collected_at_depth(&op.type_annotation, depth + 1)))
511	                }
512	                TSTypeOperatorOperator::Unique | TSTypeOperatorOperator::Readonly => {
513	                    self.ts_type_to_collected_at_depth(&op.type_annotation, depth + 1)
514	                }
515	            },
516	
517	            TSType::TSInferType(i) => {
518	                let raw = self.source[i.span.start as usize..i.span.end as usize].to_owned();
519	                CollectedType::Raw(raw)
520	            }
521	
522	            // Anything else: capture raw source text as fallback
523	            _ => {
524	                use oxc_span::GetSpan;
525	                let span = ty.span();
526	                let raw = self.source[span.start as usize..span.end as usize].to_owned();
527	                CollectedType::Raw(raw)
528	            }
529	        }
530	    }
531	
532	    /// Convert a `TSTupleElement` (which is a superset of `TSType`) to a `CollectedType`.
533	    ///
534	    /// TSTupleElement inherits all TSType variants and adds TSOptionalType and TSRestType.
535	    pub(super) fn ts_tuple_element_to_collected<'a>(&mut self, el: &TSTupleElement<'a>, depth: u8) -> CollectedType {
536	        match el {
537	            TSTupleElement::TSOptionalType(o) => {
538	                // T? in tuple → Union([T, Undefined])
539	                let inner = self.ts_type_to_collected_at_depth(&o.type_annotation, depth + 1);
540	                CollectedType::Union(vec![inner, CollectedType::Undefined])
541	            }
542	            TSTupleElement::TSRestType(r) => {
543	                // ...T[] in tuple → Array(T)
544	                CollectedType::Array(Box::new(self.ts_type_to_collected_at_depth(&r.type_annotation, depth + 1)))
545	            }
546	            // All TSType variants are inherited — we can safely transmute via span+raw fallback
547	            // but the cleanest approach is to match the known shared variants.
548	            // Since TSTupleElement inherits TSType, we cast via the span trick:
549	            other => {
550	                use oxc_span::GetSpan;
551	                let span = other.span();
552	                let raw = self.source[span.start as usize..span.end as usize].to_owned();
553	                // Try to produce a real type from source-text parsing would require re-parsing,
554	                // so instead we check common patterns via span-based raw parsing and use
555	                // the raw fallback for anything we can't directly handle.
556	                // For the common case of plain TSType variants (not TSOptionalType/TSRestType),
557	                // we need to re-interpret the element as a TSType. We can't do this safely
558	                // at runtime without unsafe, but all such variants produce valid CollectedType
559	                // via raw text. Most real tuple usage is simple types.
560	                CollectedType::Raw(raw)
561	            }
562	        }
563	    }
