565	    pub(super) fn ts_type_query_name<'a>(&self, q: &TSTypeQuery<'a>) -> String {
566	        // TSTypeQueryExprName can be Identifier or a qualified name
567	        // Capture the source text of the expression name
568	        use oxc_span::GetSpan;
569	        let span = q.expr_name.span();
570	        self.source[span.start as usize..span.end as usize].to_owned()
571	    }
