573	    pub(super) fn ts_signature_to_object_field<'a>(
574	        &mut self,
575	        member: &TSSignature<'a>,
576	        depth: u8,
577	    ) -> Option<CollectedObjectField> {
578	        match member {
579	            TSSignature::TSPropertySignature(sig) => {
580	                let name = match &sig.key {
581	                    PropertyKey::StaticIdentifier(id) => id.name.as_str().to_owned(),
582	                    PropertyKey::StringLiteral(s) => s.value.as_str().to_owned(),
583	                    _ => return None,
584	                };
585	                let collected_type = sig
586	                    .type_annotation
587	                    .as_ref()
588	                    .map(|ta| self.ts_type_to_collected_at_depth(&ta.type_annotation, depth + 1))
589	                    .unwrap_or(CollectedType::Any);
590	                let description = self.find_jsdoc(sig.span.start);
591	                Some(CollectedObjectField { name, collected_type, required: !sig.optional, description })
592	            }
593	            TSSignature::TSMethodSignature(sig) => {
594	                let name = match &sig.key {
595	                    PropertyKey::StaticIdentifier(id) => id.name.as_str().to_owned(),
596	                    PropertyKey::StringLiteral(s) => s.value.as_str().to_owned(),
597	                    _ => return None,
598	                };
599	                let params: Vec<CollectedType> = sig
600	                    .params
601	                    .items
602	                    .iter()
603	                    .map(|p| {
604	                        p.type_annotation
605	                            .as_ref()
606	                            .map(|ta| self.ts_type_to_collected_at_depth(&ta.type_annotation, depth + 1))
607	                            .unwrap_or(CollectedType::Any)
608	                    })
609	                    .collect();
610	                let param_names: Vec<Option<CompactString>> =
611	                    sig.params.items.iter().map(|p| binding_pattern_name(&p.pattern)).collect();
612	                let return_type = sig
613	                    .return_type
614	                    .as_ref()
615	                    .map(|rt| self.ts_type_to_collected_at_depth(&rt.type_annotation, depth + 1))
616	                    .unwrap_or(CollectedType::Void);
617	                Some(CollectedObjectField {
618	                    name,
619	                    collected_type: CollectedType::Function { params, param_names, return_type: Box::new(return_type) },
620	                    required: !sig.optional,
621	                    description: String::new(),
622	                })
623	            }
624	            _ => None,
625	        }
626	    }
