641	    /// Extract the name part of a TSTypeReference (for checking FC, forwardRef, etc.)
642	    pub(super) fn extract_type_ref_name<'a>(&self, tr: &TSTypeReference<'a>) -> String {
643	        self.ts_type_name_str(&tr.type_name)
