646	    /// Extract the first type argument name from a type ref's type params.
647	    ///
648	    /// Used for `FC<ButtonProps>` → "ButtonProps".
649	    /// Handles `PropsWithChildren<P>` and `Readonly<P>` wrappers.
650	    pub(super) fn extract_props_arg<'a>(
651	        &mut self,
652	        type_params: &Option<OxcBox<'a, TSTypeParameterInstantiation<'a>>>,
653	    ) -> Option<(CompactString, Vec<String>)> {
654	        let tp = type_params.as_ref()?;
655	        let first = tp.params.first()?;
656	        self.extract_type_name_from_type(first)
657	    }
658	
659	    /// Get the (name, type_args) of a TSType if it's a simple named reference.
660	    ///
661	    /// Unwraps single-layer wrappers like `PropsWithChildren<P>` and `Readonly<P>`.
662	    pub(super) fn extract_type_name_from_type<'a>(&mut self, ty: &TSType<'a>) -> Option<(CompactString, Vec<String>)> {
663	        match ty {
664	            TSType::TSTypeReference(tr) => {
665	                let name = self.extract_type_ref_name(tr);
666	                // Unwrap transparent wrappers
667	                if matches!(name.as_str(), "PropsWithChildren" | "Readonly" | "Required") {
668	                    if let Some(tp) = &tr.type_arguments {
669	                        if let Some(inner) = tp.params.first() {
670	                            return self.extract_type_name_from_type(inner);
671	                        }
672	                    }
673	                }
674	                let args = self.extract_type_args(&tr.type_arguments);
675	                Some((name.into(), args))
676	            }
677	            TSType::TSParenthesizedType(p) => self.extract_type_name_from_type(&p.type_annotation),
678	            TSType::TSUnionType(u) => {
679	                let members: Vec<CollectedType> = u.types.iter().map(|t| self.ts_type_to_collected(t)).collect();
680	                let bare = format!("__anon_{}", self.data.type_aliases.len());
681	                let scoped = self.scoped_key(&bare);
682	                self.data
683	                    .type_aliases
684	                    .insert(scoped, CollectedTypeAlias::Union { members, file_path: self.file_path.clone() });
685	                Some((bare.into(), vec![]))
686	            }
687	            TSType::TSIntersectionType(i) => {
688	                let members: Vec<CollectedType> = i.types.iter().map(|t| self.ts_type_to_collected(t)).collect();
689	                let bare = format!("__anon_{}", self.data.type_aliases.len());
690	                let scoped = self.scoped_key(&bare);
691	                self.data
692	                    .type_aliases
693	                    .insert(scoped, CollectedTypeAlias::Intersection { members, file_path: self.file_path.clone() });
694	                Some((bare.into(), vec![]))
695	            }
696	            TSType::TSTypeLiteral(_) => {
697	                // Bare inline object type used directly as props, e.g. `FC<{ x: string }>`
698	                // or `forwardRef<Elem, { x: string }>`. Synthesize an anonymous passthrough
699	                // alias so the resolver's existing alias machinery can resolve it, instead
700	                // of silently dropping the whole component (the `_ => None` fallback below).
701	                let collected = self.ts_type_to_collected(ty);
702	                let bare = format!("__anon_{}", self.data.type_aliases.len());
703	                let scoped = self.scoped_key(&bare);
704	                self.data.type_aliases.insert(
705	                    scoped,
706	                    CollectedTypeAlias::Passthrough { target: collected, file_path: self.file_path.clone() },
707	                );
708	                Some((bare.into(), vec![]))
709	            }
710	            _ => None,
711	        }
712	    }
