716	    pub(super) fn collect_extends<'a>(&mut self, ext: &TSInterfaceHeritage<'a>) -> ExtendsRef {
717	        let name = self.expression_to_ident_name(&ext.expression);
718	        let type_args = self.extract_type_args(&ext.type_arguments);
719	        self.classify_extends(&name, type_args)
720	    }
