722	    pub(super) fn expression_to_ident_name<'a>(&self, expr: &Expression<'a>) -> String {
723	        match expr {
724	            Expression::Identifier(id) => id.name.as_str().to_owned(),
725	            Expression::StaticMemberExpression(me) => {
726	                format!("{}.{}", self.expression_to_ident_name(&me.object), me.property.name.as_str())
727	            }
728	            _ => "unknown".to_owned(),
729	        }
730	    }
