807	/// Get the declared name from a Declaration node.
808	pub(super) fn declaration_name<'a>(decl: &Declaration<'a>) -> Option<&'a str> {
809	    match decl {
810	        Declaration::VariableDeclaration(vd) => vd.declarations.first().and_then(|d| match &d.id {
811	            BindingPattern::BindingIdentifier(id) => Some(id.name.as_str()),
812	            _ => None,
813	        }),
814	        Declaration::FunctionDeclaration(f) => f.id.as_ref().map(|id| id.name.as_str()),
815	        Declaration::ClassDeclaration(c) => c.id.as_ref().map(|id| id.name.as_str()),
816	        Declaration::TSTypeAliasDeclaration(ta) => Some(ta.id.name.as_str()),
817	        Declaration::TSInterfaceDeclaration(iface) => Some(iface.id.name.as_str()),
818	        Declaration::TSEnumDeclaration(e) => Some(e.id.name.as_str()),
819	        Declaration::TSModuleDeclaration(m) => match &m.id {
820	            TSModuleDeclarationName::Identifier(id) => Some(id.name.as_str()),
821	            TSModuleDeclarationName::StringLiteral(s) => Some(s.value.as_str()),
822	        },
823	        _ => None,
824	    }
825	}
