190	    /// Parse `X.Y = <right>` out of an `ExpressionStatement`. Shared by every
191	    /// scan below that looks for a specific static property name being
192	    /// assigned on an already-detected component's binding.
193	    fn static_member_assignment<'a, 'b>(
194	        &self,
195	        stmt: &'b ExpressionStatement<'a>,
196	    ) -> Option<(std::string::String, &'b str, &'b Expression<'a>)> {
197	        let Expression::AssignmentExpression(assign) = &stmt.expression else { return None };
198	        let AssignmentTarget::StaticMemberExpression(sme) = &assign.left else { return None };
199	        let obj = self.expression_to_ident_name(&sme.object);
