    }

    // ── SPEC-EXTRACTOR-001 AC-018: computed/symbol keys are silently omitted;
    // a numeric-literal key extracts as its decimal string form.

    #[test]
    fn computed_symbol_and_numeric_interface_keys() {
        let source = r#"
            interface Props {
                [key: string]: unknown;
