1	//! JSDoc extraction: find_jsdoc, extract_jsdoc_tags, parse_jsdoc_text.
2	
3	use std::collections::BTreeMap;
4	
5	use super::SourceDataCollector;
6	
7	impl<'src> SourceDataCollector<'src> {
8	    // ─── JSDoc extraction ─────────────────────────────────────────────────────
9	
10	    /// Find JSDoc comment immediately preceding the given byte offset.
11	    /// Returns empty string if none found.
12	    ///
13	    /// Marks the comment as consumed so subsequent calls for a different span cannot
14	    /// return the same comment (prevents prop JSDoc leaking into component descriptions).
15	    pub(super) fn find_jsdoc(&mut self, span_start: u32) -> String {
16	        self.find_jsdoc_with_tags(span_start).0
17	    }
18	
19	    /// Find the JSDoc comment immediately preceding the given byte offset and return
20	    /// both its description and its `@tag` map from a single lookup.
21	    ///
22	    /// Description and tags must come from the same consumed-tracking pass: an earlier
23	    /// version called a separate (non-consuming) tag scan after `find_jsdoc`, so a
24	    /// comment already claimed for one element's description was still visible to a
25	    /// later, unrelated element's tag scan — e.g. a `@deprecated` tag on one prop would
26	    /// bleed onto sibling props with no JSDoc of their own. Sharing the same consumed-set
27	    /// lookup for both makes that impossible.
28	    ///
29	    /// `self.comments` is sorted by span (source order), so the candidate window is
30	    /// located via binary search rather than a linear scan — callers run one of these
31	    /// per prop/interface/component, and a full rescan-per-call is quadratic in file size.
32	    pub(super) fn find_jsdoc_with_tags(&mut self, span_start: u32) -> (String, BTreeMap<String, String>) {
33	        const PROXIMITY_THRESHOLD: u32 = 120; // bytes — enough for blank lines + decorator
34	
35	        let upper = self.comments.partition_point(|c| c.span_end <= span_start);
36	        let mut found: Option<usize> = None;
37	        for i in (0..upper).rev() {
38	            let c = &self.comments[i];
39	            if span_start - c.span_end > PROXIMITY_THRESHOLD {
40	                // Comments are sorted ascending by span, so every earlier comment
41	                // is farther still — nothing left in range.
42	                break;
43	            }
44	            if c.is_block && !self.consumed_jsdoc.contains(&c.span_end) {
45	                found = Some(i);
46	                break;
47	            }
48	        }
49	
50	        let Some(i) = found else { return (String::new(), BTreeMap::new()) };
51	        let c = &self.comments[i];
52	        let span_end = c.span_end;
53	        let raw = &self.source[c.span_start as usize..c.span_end as usize];
54	        let text = parse_jsdoc_text(raw);
55	        let tags = extract_jsdoc_tags(raw);
56	        if !text.is_empty() || !tags.is_empty() {
57	            self.consumed_jsdoc.insert(span_end);
58	        }
59	        (text, tags)
60	    }
61	}
62	
63	// ─── JSDoc parsing ────────────────────────────────────────────────────────────
64	
65	pub(super) fn parse_jsdoc_text(raw: &str) -> String {
66	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
67	
68	    let desc_lines: Vec<&str> = inner
69	        .lines()
70	        .map(|l| {
71	            let l = l.trim();
72	            let l = l.strip_prefix("* ").or_else(|| l.strip_prefix('*')).unwrap_or(l);
73	            l
74	        })
75	        .take_while(|l| !l.starts_with('@'))
76	        .collect();
77	
78	    desc_lines.join("\n").trim().to_owned()
79	}
80	
81	pub(super) fn extract_jsdoc_tags(raw: &str) -> BTreeMap<String, String> {
82	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
83	    let mut tags: BTreeMap<String, String> = BTreeMap::new();
84	    let mut in_tags = false;
85	
86	    for line in inner.lines() {
87	        let line = line.trim();
88	        let line = line.strip_prefix("* ").or_else(|| line.strip_prefix('*')).unwrap_or(line);
89	        let line = line.trim();
90	
91	        if let Some(rest) = line.strip_prefix('@') {
92	            in_tags = true;
93	            let (tag, value) = if let Some(sp) = rest.find(char::is_whitespace) {
94	                let tag = &rest[..sp];
95	                let value = rest[sp..].trim();
96	                (tag, value)
97	            } else {
98	                (rest, "")
99	            };
100	
101	            // Special handling for @param — store as `param:propName`
102	            if tag == "param" {
103	                // Accepts both `@param propName description` and
104	                // `@param {type} propName description`.
105	                let value = value.trim_start_matches('{');
106	                let value =
107	                    if value.contains('}') { value.split_once('}').map(|x| x.1).unwrap_or("").trim() } else { value };
108	                if let Some(space) = value.find(char::is_whitespace) {
109	                    let prop_name = &value[..space];
110	                    let desc = value[space..].trim();
111	                    tags.insert(format!("param:{}", prop_name), desc.to_owned());
112	                } else if !value.is_empty() {
113	                    tags.insert(format!("param:{}", value), String::new());
114	                }
