3	use crate::config::{build_options, BuildOptionsArgs};
4	use crate::output::{print_diagnostics, print_summary, write_atomic};
5	
6	/// Watch mode never runs `--strict` — there's no CLI flag for it — so this
7	/// is always `exit_code(false)`. Named seam so `cmd_watch`'s wiring has
8	/// something unit-testable without spinning up watchexec.
9	fn watch_exit_code(output: &oxc_react_docgen_core::types::ExtractionOutput) -> i32 {
10	    output.exit_code(false)
11	}
12	
13	pub fn cmd_watch(args: crate::WatchArgs, quiet: bool, config_path: Option<&str>) -> Result<i32> {
14	    use indicatif::{ProgressBar, ProgressStyle};
15	    use owo_colors::OwoColorize;
16	
17	    let options = build_options(BuildOptionsArgs {
18	        src: &args.src,
19	        no_cross_package: false,
20	        react_version: None,
21	        cache_dir: None,
22	        html_attributes: None,
23	        config_path,
24	        extra_builtins: &[],
25	    })?;
26	
27	    if !quiet {
28	        println!();
29	        println!(
30	            "  {}  {} watching {}  {}",
31	            "⚡".yellow(),
32	            "oxc-react-docgen".bold(),
33	            options.src_dirs.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(", ").cyan(),
34	            "(press q to quit, r to re-extract)".dimmed()
35	        );
36	        println!();
37	    }
38	
39	    let pb = if !quiet {
40	        let pb = ProgressBar::new_spinner();
41	        pb.set_style(ProgressStyle::default_spinner().template("{spinner:.cyan} {msg}").into_diagnostic()?);
42	        pb.set_message("Extracting...");
43	        pb.enable_steady_tick(std::time::Duration::from_millis(80));
44	        Some(pb)
45	    } else {
46	        None
47	    };
48	
49	    let session = std::sync::Arc::new(oxc_react_docgen_core::pipeline::WatchSession::new(options.clone()));
50	    let first = session.initialize();
51	
52	    if let Some(ref pb) = pb {
53	        pb.finish_and_clear();
54	    }
55	    if !quiet {
56	        print_summary(&first, quiet);
57	        print_diagnostics(&first.diagnostics);
58	    }
59	
60	    let exit_code = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(watch_exit_code(&first)));
61	
