1	//! Import resolution map — built from `GlobalSourceData`, used read-only during resolution.
2	//!
3	//! Answers the question: "in file F, the name N was imported — what specifier and
4	//! canonical name does it refer to?"  Actual path resolution (specifier → absolute
5	//! path) is left to the caller via `oxc_resolver`.
6	
7	use camino::{Utf8Path, Utf8PathBuf};
8	use compact_str::CompactString;
9	use rustc_hash::FxHashMap;
10	
11	use crate::types::{GlobalSourceData, LexedExport};
12	
13	// ─── Public Types ─────────────────────────────────────────────────────────────
14	
15	/// Where an imported name comes from, as written in the source.
16	#[derive(Debug, Clone)]
17	pub struct ImportRef {
18	    /// The import specifier as written: `"@radix-ui/react-button"`, `"./types"`, etc.
19	    pub specifier: String,
20	    /// The exported name in the source module (original name before `as` rename).
21	    pub exported_name: CompactString,
22	    /// `true` for `import type { ... }` bindings.
23	    #[allow(dead_code)]
24	    pub is_type_only: bool,
25	}
26	
27	/// Result of walking one step of a re-export chain.
28	#[derive(Debug, Clone)]
29	pub enum ReExportStep {
30	    /// Found a named re-export — caller resolves `source_specifier` to a file and recurses.
31	    Named { source_specifier: String, source_name: String },
32	    /// Found one or more `export * from "..."` entries — caller checks each.
33	    Wildcards(Vec<String>),
34	}
35	
36	// ─── ImportResolutionMap ──────────────────────────────────────────────────────
37	
38	/// Maps `(consuming_file, local_name)` → import reference.
39	/// Built once from `GlobalSourceData`, then used read-only during parallel resolution.
40	pub struct ImportResolutionMap {
41	    /// `file_path` → (`local_name` → specifier + original exported name).
42	    /// Nested (rather than a flat `(Utf8PathBuf, CompactString)` key) so lookups can
43	    /// borrow `&Utf8Path` directly instead of cloning the whole path per call.
44	    /// Note: we store the specifier string, not the resolved file path.
45	    /// The resolver calls `oxc_resolver` to turn specifiers into absolute paths.
46	    bindings: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, ImportRef>>,
47	}
48	
49	impl ImportResolutionMap {
50	    /// Build from a fully-merged `GlobalSourceData`.
51	    /// Called once per extraction run, before parallel resolution starts.
52	    ///
53	    /// No I/O — pure data transformation.
54	    pub fn build(global: &GlobalSourceData) -> Self {
55	        let mut bindings: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, ImportRef>> = FxHashMap::default();
56	
57	        for (file_path, import_bindings) in &global.import_map {
58	            let per_file = bindings.entry(file_path.clone()).or_default();
59	            for binding in import_bindings {
60	                per_file.insert(
61	                    binding.local_name.clone(),
62	                    ImportRef {
63	                        specifier: binding.specifier.clone(),
64	                        exported_name: binding.exported_name.clone(),
65	                        is_type_only: binding.is_type_only,
66	                    },
67	                );
68	            }
69	        }
70	
71	        Self { bindings }
72	    }
73	
74	    /// Given a file and a local name used in that file, return where it was imported from.
75	    ///
76	    /// Returns `None` if the name is locally defined (not imported).
77	    pub fn find_import(&self, file: &Utf8Path, local_name: &str) -> Option<&ImportRef> {
78	        self.bindings.get(file)?.get(local_name)
79	    }
80	
81	    /// Walk one step of the re-export chain for `barrel_file`.
82	    ///
83	    /// - If a `ReExportNamed` entry matches `exported_name`, returns `Named { .. }`.
84	    /// - If no named match is found but there are `ReExportAll` entries, returns `Wildcards(..)`.
85	    /// - Returns `None` if the barrel file has no relevant re-exports.
86	    pub fn resolve_reexport_chain(
87	        &self,
88	        barrel_file: &Utf8Path,
89	        exported_name: &str,
90	        global: &GlobalSourceData,
91	    ) -> Option<ReExportStep> {
92	        let exports = global.re_export_map.get(barrel_file)?;
93	
94	        let mut wildcard_specifiers: Vec<String> = Vec::new();
95	
96	        for export in exports {
97	            match export {
98	                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } => {
99	                    if local_name == exported_name {
100	                        return Some(ReExportStep::Named {
101	                            source_specifier: source_specifier.clone(),
102	                            source_name: source_name.clone(),
103	                        });
104	                    }
105	                }
106	                LexedExport::ReExportAll { source_specifier, .. } => {
107	                    wildcard_specifiers.push(source_specifier.clone());
108	                }
109	                // Namespace re-exports and local declarations are not relevant here.
110	                _ => {}
111	            }
112	        }
113	
114	        if !wildcard_specifiers.is_empty() {
115	            Some(ReExportStep::Wildcards(wildcard_specifiers))
116	        } else {
117	            None
118	        }
119	    }
120	}
121	
122	// ─── Tests ────────────────────────────────────────────────────────────────────
123	
124	#[cfg(test)]
125	mod tests {
126	    use super::*;
127	    use crate::types::{GlobalSourceData, ImportBinding, LexedExport};
128	    use camino::Utf8PathBuf;
129	    use compact_str::CompactString;
130	
131	    /// Convenience builder for `GlobalSourceData`.
132	    fn make_global(
133	        imports: Vec<(Utf8PathBuf, Vec<ImportBinding>)>,
134	        exports: Vec<(Utf8PathBuf, Vec<LexedExport>)>,
135	    ) -> GlobalSourceData {
136	        let mut g = GlobalSourceData::default();
137	        for (path, bindings) in imports {
138	            g.import_map.insert(path, bindings);
139	        }
140	        for (path, exps) in exports {
141	            g.re_export_map.insert(path, exps);
142	        }
143	        g
144	    }
145	
146	    fn make_binding(local_name: &str, exported_name: &str, specifier: &str, is_type_only: bool) -> ImportBinding {
147	        ImportBinding {
148	            local_name: CompactString::from(local_name),
149	            exported_name: CompactString::from(exported_name),
150	            specifier: specifier.to_owned(),
151	            is_type_only,
152	        }
153	    }
154	
155	    #[test]
156	    fn test_named_import_lookup() {
157	        let file = Utf8PathBuf::from("/project/src/Button.tsx");
158	        let global = make_global(
159	            vec![(file.clone(), vec![make_binding("ButtonProps", "ButtonProps", "@radix-ui/react-button", false)])],
160	            vec![],
161	        );
162	
163	        let map = ImportResolutionMap::build(&global);
164	
165	        let result = map.find_import(&file, "ButtonProps").expect("should find import");
166	        assert_eq!(result.specifier, "@radix-ui/react-button");
167	        assert_eq!(result.exported_name.as_str(), "ButtonProps");
168	        assert!(!result.is_type_only);
169	    }
170	
171	    #[test]
172	    fn test_named_import_not_found() {
173	        let file = Utf8PathBuf::from("/project/src/Button.tsx");
174	        let global = make_global(vec![], vec![]);
175	        let map = ImportResolutionMap::build(&global);
176	
177	        assert!(map.find_import(&file, "LocalType").is_none());
178	    }
179	
180	    #[test]
181	    fn test_renamed_import() {
182	        // import { Button as Btn } from "@radix-ui/react-button"
183	        let file = Utf8PathBuf::from("/project/src/Wrapper.tsx");
184	        let global = make_global(
185	            vec![(file.clone(), vec![make_binding("Btn", "Button", "@radix-ui/react-button", false)])],
186	            vec![],
187	        );
188	
189	        let map = ImportResolutionMap::build(&global);
190	
191	        // Looking up by local alias "Btn"
192	        let result = map.find_import(&file, "Btn").expect("should find renamed import");
193	        assert_eq!(result.exported_name.as_str(), "Button");
194	        assert_eq!(result.specifier, "@radix-ui/react-button");
195	
196	        // Original name "Button" is NOT a local binding in this file
197	        assert!(map.find_import(&file, "Button").is_none());
198	    }
199	
200	    #[test]
201	    fn test_reexport_named_chain() {
202	        // barrel/index.ts: export { Foo as Bar } from "./foo"
203	        // Looking up "Bar" should return Named { source_name: "Foo", source_specifier: "./foo" }
204	        let barrel = Utf8PathBuf::from("/project/src/index.ts");
205	        let global = make_global(
206	            vec![],
207	            vec![(
208	                barrel.clone(),
209	                vec![LexedExport::ReExportNamed {
210	                    local_name: "Bar".to_owned(),
211	                    source_name: "Foo".to_owned(),
212	                    source_specifier: "./foo".to_owned(),
213	                    is_type_only: false,
214	                }],
215	            )],
216	        );
217	
218	        let map = ImportResolutionMap::build(&global);
219	
220	        match map.resolve_reexport_chain(&barrel, "Bar", &global) {
221	            Some(ReExportStep::Named { source_specifier, source_name }) => {
222	                assert_eq!(source_specifier, "./foo");
223	                assert_eq!(source_name, "Foo");
224	            }
225	            other => panic!("expected Named, got {:?}", other),
226	        }
227	    }
228	
229	    #[test]
230	    fn test_reexport_named_no_match() {
231	        // The barrel exports "Bar" but we ask for "Baz"
232	        let barrel = Utf8PathBuf::from("/project/src/index.ts");
233	        let global = make_global(
234	            vec![],
235	            vec![(
236	                barrel.clone(),
237	                vec![LexedExport::ReExportNamed {
238	                    local_name: "Bar".to_owned(),
239	                    source_name: "Foo".to_owned(),
240	                    source_specifier: "./foo".to_owned(),
241	                    is_type_only: false,
242	                }],
243	            )],
244	        );
245	
246	        let map = ImportResolutionMap::build(&global);
247	        assert!(map.resolve_reexport_chain(&barrel, "Baz", &global).is_none());
248	    }
249	
250	    #[test]
251	    fn test_reexport_all() {
252	        // barrel/index.ts: export * from "./types"
253	        let barrel = Utf8PathBuf::from("/project/src/index.ts");
254	        let global = make_global(
255	            vec![],
256	            vec![(
257	                barrel.clone(),
258	                vec![LexedExport::ReExportAll { source_specifier: "./types".to_owned(), is_type_only: false }],
259	            )],
260	        );
261	
262	        let map = ImportResolutionMap::build(&global);
263	
264	        // resolve_reexport_chain for any name should return Wildcards
265	        match map.resolve_reexport_chain(&barrel, "AnyName", &global) {
266	            Some(ReExportStep::Wildcards(specs)) => {
267	                assert_eq!(specs, vec!["./types"]);
268	            }
269	            other => panic!("expected Wildcards, got {:?}", other),
270	        }
271	    }
272	
273	    #[test]
274	    fn test_reexport_named_takes_priority_over_wildcard() {
275	        // If a barrel has both a named re-export matching the name AND wildcards,
276	        // the named re-export wins (returned first).
277	        let barrel = Utf8PathBuf::from("/project/src/index.ts");
278	        let global = make_global(
279	            vec![],
280	            vec![(
281	                barrel.clone(),
282	                vec![
283	                    LexedExport::ReExportAll { source_specifier: "./everything".to_owned(), is_type_only: false },
284	                    LexedExport::ReExportNamed {
