297	            Some(ReExportStep::Named { source_specifier, source_name }) => {
298	                assert_eq!(source_specifier, "./target");
299	                assert_eq!(source_name, "Target");
300	            }
301	            other => panic!("expected Named, got {:?}", other),
302	        }
