1	//! Named-type resolution index — interfaces, type aliases, and their declared
2	//! generic type parameters, indexed for fast `(file, name)` lookup.
3	//!
4	//! Built once from `GlobalSourceData` before parallel resolution starts,
5	//! mirroring `import_map.rs::ImportResolutionMap`'s split: `GlobalSourceData`'s
6	//! own maps stay flat (`FxHashMap<String, T>`, unchanged — `merge()` and the
7	//! resolver test module's fixture-building code both depend on that shape),
8	//! while this index restructures them into nested
9	//! `FxHashMap<Utf8PathBuf, FxHashMap<CompactString, T>>` maps so a lookup can
10	//! borrow `&Utf8Path`/`&str` directly instead of allocating a fresh
11	//! `"{file}:{name}"` String per call. `lookup_interface`/`lookup_type_alias`
12	//! (the two hottest of these) run recursively for every prop, every generic
13	//! argument, and every extends clause across the whole component tree — the
14	//! same cost `ImportResolutionMap` and `ResolutionContext::enum_bare_index`
15	//! were already built to eliminate for import/enum lookups elsewhere in this
16	//! resolver.
17	
18	use camino::{Utf8Path, Utf8PathBuf};
19	use compact_str::CompactString;
20	use rustc_hash::FxHashMap;
21	
22	use crate::types::{CollectedInterface, CollectedTypeAlias, GlobalSourceData, TypeName};
23	
24	pub(crate) struct NamedTypeIndex {
25	    interfaces: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedInterface>>,
26	    type_aliases: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedTypeAlias>>,
27	    type_alias_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>>,
28	    interface_type_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>>,
29	}
30	
31	/// What `lookup_ambient` found at a given ambient lib file, mirroring the
32	/// two shapes a same-file/imported lookup can also produce.
33	pub(crate) enum AmbientMatch<'a> {
34	    Interface,
35	    TypeAlias(&'a CollectedTypeAlias),
36	}
37	
38	impl NamedTypeIndex {
39	    /// Build from a fully-merged `GlobalSourceData`. Called once per
40	    /// resolution pass (`ResolutionContext::build`), before parallel
41	    /// resolution starts. No I/O — pure data transformation.
42	    ///
43	    /// Splits each flat `"{file}:{name}"` key on its *last* `:` — the same
44	    /// technique `ResolutionContext::enum_bare_index`/`const_array_bare_index`
45	    /// already use — rather than requiring a value-embedded `file_path` to
46	    /// anchor the split, so this works uniformly across all four maps
47	    /// (`type_alias_params`/`interface_type_params`'s own values carry no
48	    /// `file_path` of their own to anchor on).
49	    pub(crate) fn build(global: &GlobalSourceData) -> Self {
50	        let mut interfaces: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedInterface>> = FxHashMap::default();
51	        let mut interface_type_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>> =
52	            FxHashMap::default();
53	        for (key, iface) in &global.interfaces {
54	            let Some((file, name)) = key.rsplit_once(':') else { continue };
55	            let file = Utf8PathBuf::from(file);
56	            interfaces.entry(file.clone()).or_default().insert(CompactString::from(name), iface.clone());
57	            if let Some(params) = global.interface_type_params.get(key) {
58	                interface_type_params.entry(file).or_default().insert(CompactString::from(name), params.clone());
59	            }
60	        }
61	
62	        let mut type_aliases: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedTypeAlias>> =
63	            FxHashMap::default();
64	        let mut type_alias_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>> =
65	            FxHashMap::default();
66	        for (key, alias) in &global.type_aliases {
67	            let Some((file, name)) = key.rsplit_once(':') else { continue };
68	            let file = Utf8PathBuf::from(file);
69	            type_aliases.entry(file.clone()).or_default().insert(CompactString::from(name), alias.clone());
70	            if let Some(params) = global.type_alias_params.get(key) {
