73	impl WatchSession {
74	    /// Create an empty WatchSession (call `initialize()` before first use).
75	    pub fn new(options: PipelineOptions) -> Self {
76	        Self {
77	            options,
78	            global: ArcSwap::new(Arc::new(GlobalSourceData::default())),
79	            reverse_deps: ArcSwap::new(Arc::new(ReverseDeps { inner: Default::default() })),
80	            source_cache: DashMap::new(),
81	            component_cache: DashMap::new(),
82	            diagnostics: DashMap::new(),
83	            ambient_global_files: std::sync::OnceLock::new(),
84	            initialized: Mutex::new(false),
85	        }
86	    }
87	
88	    /// Run a full cold extraction to populate this session's caches.
89	    ///
90	    /// Idempotent — concurrent or repeated calls return the existing snapshot
91	    /// without re-running extraction.
92	    pub fn initialize(&self) -> ExtractionOutput {
93	        let mut guard = self.initialized.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
94	        if *guard {
95	            return self.snapshot();
96	        }
97	
98	        // Single real pipeline run (discover, parse, merge, Full-mode
99	        // @types/react, ambient lib.d.ts, resolve) shared with the one-shot
100	        // extract() path — see extract_with_global's doc comment. Previously
101	        // this rebuilt GlobalSourceData by hand here, which skipped the
102	        // Full-mode/ambient-lib.d.ts merges entirely: the cold `output` below
103	        // was correct (it came from a real extract() call), but the `global`
104	        // this session persists for every subsequent update_file() was not.
105	        let (output, global, per_file_data) = super::extract_with_global(&self.options, true);
106	
107	        for (path, data) in per_file_data {
108	            self.source_cache.insert(path, data);
109	        }
110	
111	        let _ = self.ambient_global_files.set(crate::resolver::compute_ambient_global_files(&self.options));
112	        self.reverse_deps.store(Arc::new(ReverseDeps::build(&global)));
113	        self.global.store(global);
114	
115	        // Seed component cache from the cold output.
116	        for (name, entry) in &output.components {
117	            self.component_cache.insert(name.clone(), entry.clone());
118	        }
119	
120	        *guard = true;
121	        output
122	    }
123	
124	    /// Return the current full extraction state from the in-memory caches.
125	    /// Suitable for writing to `--out` after each incremental update.
126	    pub fn snapshot(&self) -> ExtractionOutput {
127	        let components: std::collections::BTreeMap<String, ComponentEntry> =
128	            self.component_cache.iter().map(|r| (r.key().clone(), r.value().clone())).collect();
129	        let global = self.global.load();
130	        let enums: std::collections::BTreeMap<String, Vec<EnumEntry>> =
131	            global.enums.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
132	
133	        // DashMap iteration order is arbitrary — sort by path for deterministic output.
134	        let mut by_path: Vec<(Utf8PathBuf, Vec<Diagnostic>)> =
135	            self.diagnostics.iter().map(|r| (r.key().clone(), r.value().clone())).collect();
136	        by_path.sort_by(|a, b| a.0.cmp(&b.0));
137	        let diagnostics: Vec<Diagnostic> = by_path.into_iter().flat_map(|(_, ds)| ds).collect();
138	
139	        // Only `components_extracted` is populated here — the other ExtractionStats
140	        // fields (files_parsed, dts_cache_hits, duration_ms, tier1/tier3/opaque
141	        // counts) describe a single extract() run's own bookkeeping, which this
142	        // session doesn't accumulate across incremental update_file() calls. A
143	        // consumer reading watch --out's stats block for anything but the
144	        // component count sees zeros — a known, narrower gap than reporting
145	        // componentsExtracted itself as 0 regardless of how many components exist.
146	        let stats = ExtractionStats { components_extracted: components.len() as u32, ..ExtractionStats::default() };
