165	    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
166	        let start = Instant::now();
167	
168	        // `discover_files`'s directory walk (via the `ignore` crate) resolves
169	        // symlinks in the paths it reports — e.g. macOS's `/var` -> `/private/var`
170	        // — so every path already stored in `global`/`reverse_deps` is in that
171	        // resolved form. A file-watcher-reported `changed` path is not
172	        // guaranteed to match unless it's canonicalized the same way; without
173	        // this, `reverse_deps.affected()` below would look up the wrong key and
174	        // silently find no dependents at all.
175	        let changed = canonicalize_best_effort(changed);
176	        let changed = changed.as_path();
177	
178	        // 1. Re-parse the changed file.
179	        let mut io_diagnostic: Option<Diagnostic> = None;
180	        let source = match std::fs::read_to_string(changed) {
181	            Ok(s) => s,
182	            Err(e) => {
183	                io_diagnostic = Some(Diagnostic::io_read_error(changed, &e));
184	                String::new()
185	            }
186	        };
187	        let new_data = crate::extractor::parse_file(changed, &source);
188	        self.source_cache.insert(changed.to_owned(), new_data.clone());
189	
190	        // 2. Patch GlobalSourceData atomically using rcu (read-copy-update).
191	        // rcu retries if the pointer was swapped by a concurrent update_file call,
192	        // preventing lost-update races under parallel file change events.
