1	//! Named-type resolution index — interfaces, type aliases, and their declared
2	//! generic type parameters, indexed for fast `(file, name)` lookup.
3	//!
4	//! Built once from `GlobalSourceData` before parallel resolution starts,
5	//! mirroring `import_map.rs::ImportResolutionMap`'s split: `GlobalSourceData`'s
6	//! own maps stay flat (`FxHashMap<String, T>`, unchanged — `merge()` and the
7	//! resolver test module's fixture-building code both depend on that shape),
8	//! while this index restructures them into nested
9	//! `FxHashMap<Utf8PathBuf, FxHashMap<CompactString, T>>` maps so a lookup can
10	//! borrow `&Utf8Path`/`&str` directly instead of allocating a fresh
11	//! `"{file}:{name}"` String per call. `lookup_interface`/`lookup_type_alias`
12	//! (the two hottest of these) run recursively for every prop, every generic
13	//! argument, and every extends clause across the whole component tree — the
14	//! same cost `ImportResolutionMap` and `ResolutionContext::enum_bare_index`
15	//! were already built to eliminate for import/enum lookups elsewhere in this
16	//! resolver.
17	
18	use camino::{Utf8Path, Utf8PathBuf};
19	use compact_str::CompactString;
20	use rustc_hash::FxHashMap;
21	
22	use crate::types::{CollectedInterface, CollectedTypeAlias, GlobalSourceData, SourceData, TypeName};
23	
24	#[derive(Clone, Default)]
25	pub(crate) struct NamedTypeIndex {
26	    interfaces: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedInterface>>,
27	    type_aliases: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedTypeAlias>>,
28	    type_alias_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>>,
29	    interface_type_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>>,
30	}
31	
32	/// What `lookup_ambient` found at a given ambient lib file, mirroring the
33	/// two shapes a same-file/imported lookup can also produce.
34	pub(crate) enum AmbientMatch<'a> {
35	    Interface,
36	    TypeAlias(&'a CollectedTypeAlias),
37	}
38	
39	impl NamedTypeIndex {
40	    /// Build from a fully-merged `GlobalSourceData`. Called once per
41	    /// resolution pass (`ResolutionContext::build`), before parallel
42	    /// resolution starts. No I/O — pure data transformation.
43	    ///
44	    /// Splits each flat `"{file}:{name}"` key on its *last* `:` — the same
45	    /// technique `ResolutionContext::enum_bare_index`/`const_array_bare_index`
46	    /// already use — rather than requiring a value-embedded `file_path` to
47	    /// anchor the split, so this works uniformly across all four maps
48	    /// (`type_alias_params`/`interface_type_params`'s own values carry no
49	    /// `file_path` of their own to anchor on).
