53	            type_aliases: FxHashMap::default(),
54	            type_alias_params: FxHashMap::default(),
55	            interface_type_params: FxHashMap::default(),
56	        };
57	        index.insert_flat_maps(
58	            &global.interfaces,
59	            &global.interface_type_params,
60	            &global.type_aliases,
61	            &global.type_alias_params,
62	        );
63	        index
