    let v = serde_json::json!({"obj": [{"t": "str", "req": true, "desc": "d"}]});
    assert!(
        CollectedType::from_json_value(&v).is_err(),
        "an object field with no 'name' key must be rejected, not silently default to an empty name"
    );
}

