    components: {},
    enums: {},
    diagnostics: [],
    stats: {
      componentsExtracted: 0,
      componentsSkipped: 0,
      filesParsed: 0,
      dtsFilesParsed: 0,
      dtsCacheHits: 0,
      durationMs: 0,
      tier1Count: 0,
      tier3Count: 0,
      opaqueCount: 0,
    },
  }
