}

#[cfg(feature = "pdk")]
fn format_graph_error_json(e: &callisto_graph::error::GraphError) -> serde_json::Value {
    serde_json::json!({
        "schemaVersion": callisto_model::SCHEMA_VERSION,
        "error": {
            "code": "E_GRAPH",
            "message": e.to_string(),
        }
    })
}

